// frontend/src/components/Archive/ArchiveList.js
import React, { useState, useEffect, useCallback } from 'react';
import { archiveApi } from '../../services/api';
import './ArchiveList.css';

const ArchiveList = () => {
  const [archives, setArchives] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Загрузка всех архивов/трансляций с бэкенда
  const loadArchives = useCallback(async () => {
    try {
      setLoading(true);
      const response = await archiveApi.getAll(); // или api.post.getBroadcasts() — зависит от твоего api.js
      setArchives(response.data);
      setError(null);
    } catch (err) {
      console.error('Ошибка загрузки архивов:', err);
      setError('Не удалось загрузить архивы');
    } finally {
      setLoading(false);
    }
  }, []);

  // Удаление архива
  const handleDelete = async (id) => {
    if (!window.confirm('Удалить этот архив навсегда?')) return;
    try {
      await archiveApi.delete(id);
      setArchives(prev => prev.filter(a => a.id !== id));
    } catch (err) {
      alert('Не удалось удалить архив');
    }
  };

  // Подписка на WebSocket-уведомления о новых архивах
  useEffect(() => {
    loadArchives();

    const handleNewArchive = (e) => {
      if (e.detail?.type === 'new_archive' || e.detail?.type === 'new_broadcast') {
        loadArchives(); // моментальное обновление
      }
    };

    window.addEventListener('newNotification', handleNewArchive);
    return () => window.removeEventListener('newNotification', handleNewArchive);
  }, [loadArchives]);

  if (loading) return <div className="loading">Загрузка архивов...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="archive-list">
      <h2>Архив трансляций и записей</h2>
      <div className="archive-grid">
        {archives.map(archive => (
          <div key={archive.id} className="archive-card">
            <h3>{archive.title}</h3>
            <p>{archive.description}</p>
            <small>Дата: {new Date(archive.createdAt).toLocaleDateString('ru-RU')}</small>
            <div className="actions">
              <button onClick={() => window.open(archive.streamUrl || archive.videoUrl, '_blank')}>
                Смотреть
              </button>
              <button onClick={() => handleDelete(archive.id)} className="delete-btn">
                Удалить
              </button>
            </div>
          </div>
        ))}
      </div>
      {archives.length === 0 && <p>Пока нет архивов</p>}
    </div>
  );
};

export default ArchiveList;
